import{_ as t,C as o,o as l,c as r,j as e,a as i,E as s,a6 as n}from"./chunks/framework.CnPv4DE1.js";const k=JSON.parse('{"title":"20到30岁是新手教程阶段，别把它搞砸了","description":"","frontmatter":{"title":"20到30岁是新手教程阶段，别把它搞砸了","originalTitle":"20-30 Years Old Is The Tutorial Phase, Don’t F*ck It Up","date":"2025-07-03","originalUrl":"https://thedankoe.com/letters/20-30-years-old-is-the-tutorial-phase-dont-fck-it-up/","minutes":11,"sourceHash":"99629f361af978bf58e8574569bffb0edee7abc779b95975b80a838dfc2a557d","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/20-30-years-old-is-the-tutorial-phase-dont-fck-it-up/"}]]},"headers":[],"relativePath":"letters/20-30-years-old-is-the-tutorial-phase-dont-fck-it-up.md","filePath":"letters/20-30-years-old-is-the-tutorial-phase-dont-fck-it-up.md"}'),h={name:"letters/20-30-years-old-is-the-tutorial-phase-dont-fck-it-up.md"};function d(u,p,c,f,m,q){const a=o("ArticleMeta");return l(),r("div",null,[p[0]||(p[0]=e("h1",{id:"_20到30岁是新手教程阶段-别把它搞砸了",tabindex:"-1"},[i("20到30岁是新手教程阶段，别把它搞砸了 "),e("a",{class:"header-anchor",href:"#_20到30岁是新手教程阶段-别把它搞砸了","aria-label":'Permalink to "20到30岁是新手教程阶段，别把它搞砸了"'},"​")],-1)),s(a),p[1]||(p[1]=n('<p>这封信会惹恼一些人，因为它是写给特定类型的人的。</p><p>在大多数人看来，我会显得像个不体贴的混蛋，但这是我唯一能把这个情况的严重性传达出去的方式。</p><p>话虽如此，从现在这一刻起，请把&quot;细致体谅&quot;关掉。</p><p>那些对这里的赤裸真相感到愤怒的人，往往是那些生活相当糟糕的人。他们在20到25岁之后就再也没有成长过了。</p><p>他们是那些从未意识到这一点的人：</p><p><em>充分利用你20多岁的最好方式，就是让它们成为你最糟糕的岁月。</em></p><p>你看，你有两个选择：</p><ul><li>利用你的20多岁，成为你本该成为的那个人。</li><li>在你一生中反复重复同样的6个月。</li></ul><p>如果你没有在20多岁时几乎把自己的潜力发挥到极致，你只要观察一下社会，就会看到自己变得跟其他人一样。</p><p>你会陷入焦虑、不堪重负、以及试图重现上一次人生巅峰体验的循环之中。你去同样的酒吧和狂欢派对。你玩同样的电子游戏。你以为这是你人生中最棒的体验，因为你年纪够大能去做新鲜事，却还没有足够的智慧意识到，这些其实是人所能体验到的最低层次的高峰，于是你就用这些浅薄的活动来填满自己的生活。</p><p>大多数人在23岁左右就停滞不前了。</p><p>当你诚实地问他们，他们的生活正在朝什么方向发展时，他们其实无话可说，所以他们会自信地说，他们&quot;只是在过日子&quot;。</p><p>问题在于，你没有意识到停滞不前会带来什么后果。</p><p>如果你意识到了，你就没有别的选择，只能改变。</p><p>大多数人到了30岁时，情绪成熟度还停留在15岁的水平。世界飞速向前推进，而你的心智、身体、精神、以及财务状况却原地不动。但问题就在这里。原地不动只是一种幻觉。在你毫不费力的情况下，你会慢慢把自己挖进一个平庸的坑里，而这个坑只会变得越来越难爬出来。</p><p>你的20多岁是新手教程，不是正式游戏。</p><p>是准备阶段，不是正赛。</p><p>所以，这里有3个要避开的陷阱，以及3种能扭转全局的方法。</p><p>如果你能在20多岁时为自己打好基础，那么即便青春不再站在你这边，你的生活质量也只会持续提升。</p><h3 id="不要听信任何没有过上你想要的生活的人的话。" tabindex="-1">不要听信任何没有过上你想要的生活的人的话。 <a class="header-anchor" href="#不要听信任何没有过上你想要的生活的人的话。" aria-label="Permalink to &quot;不要听信任何没有过上你想要的生活的人的话。&quot;">​</a></h3><p>拥有你想要的那种生活的人是稀有的。</p><p>占人口的1%。</p><p>可能更少。</p><p>剩下的99%是那些喜欢喋喋不休地告诉你该怎么过自己的人生，而他们自己却把人生浪费掉了。他们没有取得任何伟大的成就，所以他们坚决要说服你，人生中最伟大的事情就是他们做过的那些事——而那些事根本称不上伟大。</p><p>他们会告诉你要更现实一点。目标定低一点。像他们一样。享受你的20多岁！去找份工作。制定预算。把你那点微薄的存款拿去投资。过一种无聊、机械的生活，做你讨厌的工作，一直到你50岁，仿佛这是某种扭曲的成年礼。很多人说他们是为你的好，但实际上，他们只是不想在你面前感到自己低人一等。</p><p>拥有你想要的那种生活的人，往往很安静。</p><p>他们很难被找到。</p><p>留心去寻找他们。</p><p>对大多数人来说，把父母、老师或同龄人的建议当真，就是一份死刑判决书。</p><h3 id="快速尝一尝各种干扰的滋味。" tabindex="-1">快速尝一尝各种干扰的滋味。 <a class="header-anchor" href="#快速尝一尝各种干扰的滋味。" aria-label="Permalink to &quot;快速尝一尝各种干扰的滋味。&quot;">​</a></h3><p>大多数人把自己的青春当作一种货币，而不是投资本金。</p><p>他们纵情派对。他们吸烟。虽然这些事情本身并不是世界末日，但它们摧毁了年轻所带来的巨大好处：时间、精力、专注力。</p><p>我也曾是个愚蠢的大学生，但我手头总有一件正在做的事，某天可以&quot;买回我的自由&quot;。</p><p>我不是叫你彻底避开这些事情。事实上，你反而应该尽快尝一尝这些东西的滋味，好让你能把它们识别为错误。相反，我要告诉你的是：<em>设定一个改变人生的目标，一个要求你拿出最佳状态的目标，这样你才能注意到自己的堕落所带来的影响。</em></p><p>普通人看不出喝酒和吸烟有什么问题，因为他们的生活并不要求高水平的表现。他们做着一份自己宁愿不去做的办公室工作，所以宿醉和懒散其实没什么大不了。</p><p>然而，这些并不是唯一的社交干扰。</p><p>我明白，你是个渴望体验这个世界的年轻人，而且你的荷尔蒙从出生起就被避孕药和环境毒素搞得一塌糊涂，但不，你不会在你处于自己最糟糕状态时，遇到你一生的爱人。</p><p>如果你在追求一种非平庸的人生，你会很快变得让你的朋友和伴侣无法与你产生共鸣，除非你不断给自己的潜力泼冷水，以避免想到在追求自身最高版本的过程中会失去他们。</p><p>你不需要避免社交或约会，但如果你不想与99%的人产生共鸣——你很可能确实不想——那就习惯去爱惜你与自己相处的时间。</p><h3 id="尽你所能-永远不要去打一份工。" tabindex="-1">尽你所能，永远不要去打一份工。 <a class="header-anchor" href="#尽你所能-永远不要去打一份工。" aria-label="Permalink to &quot;尽你所能，永远不要去打一份工。&quot;">​</a></h3><p>在我大约15岁的时候，我有过一次强烈的洞察爆发。</p><p><em>如果我像大多数人一样去找一份普通的工作，我最终会变成大多数人那样。我三分之一的时间会在我接受聘用的那一刻起就消失。另外三分之一的时间会花在睡眠上。而最后三分之一的时间会用来做毫无价值的事情，因为你讨厌的工作——不管多么简单——都是这世上最消耗人的事情。</em></p><p>对于那些读到这里、并且认同我说的大部分内容的人，我知道你是什么样的人，接下来这句话对你来说不会是什么震撼：</p><p>你需要创业。</p><p>立刻。</p><p>你不是那种会在评论区愤怒打字，说&quot;不是每个人都应该创业&quot;的人。</p><p>你是那种想要<em>掌控</em>自己时间、精力和金钱的人。你明白，美好的生活源自于不断增加的挑战水平，因为那正是你自我发展的方式，而在99%的工作中，挑战水平在1到2年内就会陷入停滞。它会从心理上把你阉割掉。</p><p>你到底创办什么样的生意其实并不重要，因为2到3年后你所做的事情将会完全不同。</p><p>你第一次不会做对。</p><p>所以一开始要保持简单。</p><p>做一些低成本、入门级、且受欢迎的事情（因为饱和恰恰说明人们需要它，而且95%的人都做得很差，所以只要你有一丝野心，你就能让它奏效）。</p><p>这是目前从新手到进阶的商业元规则，风险最小：</p><ul><li>出售一项服务（自由职业或能动性服务）</li><li>在做手动外联的同时打造受众群体</li><li>推出一款信息产品或社群</li><li>现在你有了一套技能和现金流</li><li>雇佣一个团队，或者创办一家软件或电商公司</li></ul><p>不用担心该学什么技能，因为我们很快就会谈到这个话题。</p><h3 id="设定那些真正让你害怕的目标。" tabindex="-1">设定那些真正让你害怕的目标。 <a class="header-anchor" href="#设定那些真正让你害怕的目标。" aria-label="Permalink to &quot;设定那些真正让你害怕的目标。&quot;">​</a></h3><p>在我开始写这封信的这一部分时，我感到胸口发紧，眼睛湿润，因为我忍不住希望你们所有人都有机会体会到那种回顾自己人生、心想&quot;真不敢相信我已经走了这么远&quot;的感觉。</p><p>小时候的Dan曾有过梦想，但我从未想过自己真的会写出两本书，建立起如此广泛的影响力，成为一家规模虽小却在不断成长的创业公司的CEO，并过上如此简单却充实的生活。</p><p>追求卓越，在那些不理解的人眼中，瞬间就能被贬斥为物质主义。</p><p>但那里面有些东西。</p><p>某种深刻的东西。</p><p>一种强大到无法用任何其他方式复制的感觉。</p><p>一种能量来源，其强劲程度，连大型制药公司最强的兴奋剂都无法比拟。</p><p>一种宇宙般的牵引力，要求你成为自己最高的版本。</p><p>为了复制这种感觉，我想让你拿出一张纸。</p><p>标题写上&quot;10个目标，10年&quot;。</p><p>写下10个让你感到不适的目标。</p><p>把它们分摊到10年的时间跨度里。</p><p>每年只专注于一个巨大的目标。</p><p>为什么？</p><p>你的心智会不断扩张，去填满那些设定要实现的目标。</p><p>打造一家100万美元的公司和一家1亿美元的公司，所需要付出的努力量是相同的，但行动方式不同。</p><p>有人甚至可以说，一家本地咖啡店的老板比某个在线业务的老板工作要努力得多，但赚得却少得多。这里省略了很多背景信息，但别忽略了重点。</p><p>如今这已成常识：单独的努力工作本身并不会带来太多成果。</p><p>你需要识别出那些能带来最大回报的行动，而如果你的目标不够宏大，你就无法识别出足够宏大的行动。</p><p>最大的风险就是完全没有风险，而那些看似荒诞不经的目标会改变你的大脑。</p><p>关于这一点的解释，我留到另一封信里再说。</p><h3 id="尽你所能多赚钱。" tabindex="-1">尽你所能多赚钱。 <a class="header-anchor" href="#尽你所能多赚钱。" aria-label="Permalink to &quot;尽你所能多赚钱。&quot;">​</a></h3><p>金钱是个棘手的东西。</p><p>它在每个人生活中占据如此大的比重，以至于它已经和自我价值感、道德观、以及生存问题交织在了一起，所以人们很少能看清它的真实本质。</p><p>你的父母告诉你要存钱。</p><p>你的牧师告诉你要唾弃它。</p><p>你的文化告诉你它不重要。</p><p>于是你没有把它列为优先事项，而一大堆只能靠钱来解决的问题，开始涌进你的生活，与此同时你却困在只能挣很少钱的境地里。</p><p>很少有人真正决定越过他人的道德标榜，去形成自己独立的看法，因为要做到这一点，他们就必须投入时间和脑力去致富。他们会变成他们所憎恨的那种人，即便他们从未见过那种人。他们活在一个充满谎言的脑袋里，而这些谎言影响着他们在这个世界上的机会。</p><p>金钱深深地嵌入到你的心智、身体、精神、以及显而易见的财务发展之中。我们并不生活在前工业时代。不，你不能像你的祖先那样生活，我甚至怀疑你根本不想那样活——更别提你其实是害怕金钱、拒绝承担赚钱的责任这一事实了。</p><p>&quot;但是Dan，如果我只想赚到刚好够用的钱呢？&quot;</p><p>那完全没问题，但再说一次，你这样是在限制自己能够在生活多个领域中承担的挑战水平。你可以大体上感到幸福和满足，但我这里说的，是专门针对那些无法忍受一想到自己会在人生某个时刻反复重复同样6个月的人。</p><p>钱可能既危险又邪恶，但没有它，你造不出火箭，也养不活全世界。金钱是一种全球公认的价值形式，很少有人会在没有它的情况下以那样的动力去工作。它是一个了不起的构造。而无论进化历程中会涌现出什么更宏大的问题和创新，它们大概都会需要某种形式的金钱，无论是纸币，还是任何代表价值交换而出现的货币形式。</p><p>事实是，赚钱是一项可以像其他任何技能一样被培养出来的技能。</p><p>你不擅长赚钱，是因为你的身份认同太紧地绑定在不切实际的意识形态上，这扭曲了你对一切与金钱相关事物的认知。</p><p>你学一种乐器或者玩好一款电子游戏的方式，其实再清楚不过了。</p><p>你拿起那件乐器。你学习基础知识。你尝试弹奏一首曲子。你弹得很烂。你的大脑开始建立起能让你弹好这首曲子的神经通路。你选一首更难的曲子。你又弹得很烂。你重复这个过程。</p><p>玩乐器和电子游戏时，没有 <em>风险</em>。</p><p>失败了也无所谓。</p><p>但如果你在赚钱这件事上失败了，你就没法不去担心别人会怎么看你、你浪费了多少时间、你有多肤浅、以及这件事到底能不能替代你现在的收入来源。</p><p>大多数人在技能习得这件事上，方法完全搞反了。</p><p>这不是要你去研究你能找到的每一个信息源。</p><p>而是要 <em>真正下场去玩这个游戏，然后根据上一次做错的地方去改进。</em></p><p>当你弹吉他时，你会先选一首你想学会弹的歌。</p><p>你尝试去弹，你失败了，然后你学到了那首歌里用到的一点小技巧。学会那个技巧之后，再学下一个，再下一个，慢慢地你就能不用去专门研究什么，也能弹很多歌了。</p><p>如果你想赚更多钱，那就去玩一个能带来金钱结果的游戏，一直玩到你赢为止。</p><h3 id="实现自我实现。" tabindex="-1">实现自我实现。 <a class="header-anchor" href="#实现自我实现。" aria-label="Permalink to &quot;实现自我实现。&quot;">​</a></h3><p>如果统领你人生中所有其他目标的那个最高目标不是自我实现，那它就是自我破坏。</p><p>你所采取的每一个行动，都必须与自我实现这个目的保持一致。</p><p>如果不是这样，那我会认为，你做你所做的事情，背后其实并没有一个深层的理由。</p><p>这件事的严重性很难解释清楚。</p><p>大多数人从不去想他们的行动会把他们带向怎样的人生。</p><p>他们把目光短浅地聚焦在短期的快乐上，这种快乐会慢慢地把他们打得粉碎，而他们自己却毫无察觉，直到几十年后才发现。那是你能想象到的最糟糕的境地——追上你的健康问题，一颗无法适应不断变化的技术环境的大脑。你所采取的行动从来都不是完全清醒的选择，所以它们也从未导向任何伟大的结果。</p><p>我不该非得向你展示那几十年来充分剖析人类需求与发展的心理学研究。我不该非得向你解释：如果你不去自我实现，你就会淹没在本可避免的痛苦之中。</p><p>为了你自己好，你需要训练你的心智去拉远视角。</p><p>去采用你最高版本自我的视角，并实时与那个自我商量。</p><p>在做任何大小决定之前，考虑以下这两件事，必须变得比第二天性还要根深蒂固：</p><ul><li>我想成为谁？</li><li>我不想成为谁？</li></ul><p>然后，让你的决定被这两者共同塑造。</p><p>你不需要做到完美，但要意识到，大多数人在他们的一生中从未做出过一个清醒的决定。</p><p>如果你哪怕只有30%的时候能做出正确的选择，那些行动就足以从根本上把你的未来塑造得更好。</p><p>感谢你的阅读。</p><p>希望这篇文章没有让太多人生气。</p><p>——Dan</p><p>附言：作为对你完整读完这篇文章的感谢，<a href="https://letters.thedankoe.com/88de5d98" target="_blank" rel="noreferrer">这里是一个链接，可获得25%的折扣</a>，用于购买这个 substack 的高级版本（包含提示词、营销策略，以及一套完整的一人企业启动课程）。</p><hr><p><a href="/en/letters/20-30-years-old-is-the-tutorial-phase-dont-fck-it-up">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',122))])}const b=t(h,[["render",d]]);export{k as __pageData,b as default};
